(function(root,factory){if(typeof module!=='undefined')module.exports=factory;else root.ClinicCategoryPage=factory;})(typeof window!=='undefined'?window:this,function(key){
 const data=typeof module!=='undefined'?require('./category-data.js'):window.ClinicCategoryData;
 const visual=typeof module!=='undefined'?require('./sub-visual.js'):window.ClinicSubVisual;
 const reservation=typeof module!=='undefined'?require('./eye-reservation.js'):window.ClinicEyeReservation;
 const booking=typeof module!=='undefined'?require('./cataract-booking.js'):window.ClinicCataractBooking;
 const p=data[key];if(!p)return '';
 const mark=label=>`<p class="uc-label"><img src="assets/favicon.svg" alt="Clinic" aria-hidden="true"><span>${label}</span></p>`;
 const graphic=(g,i)=>`<figure class="uc-graphic"><div class="uc-graphic-top"><svg viewBox="0 0 100 70" aria-hidden="true"><path d="M5 35Q50 -5 95 35Q50 75 5 35Z"/><circle cx="50" cy="35" r="17"/><circle cx="50" cy="35" r="7"/></svg><span>${i?'CARE & CHECK':'UNDERSTANDING'}</span></div><div class="uc-diagram">${g.slice(1).map((t,j)=>`<div class="uc-diagram-node"><span class="uc-diagram-dot" aria-hidden="true"></span><strong>${t}</strong></div>${j<2?'<span class="uc-diagram-arrow" aria-hidden="true">→</span>':''}`).join('')}</div><figcaption>${g[0]}</figcaption></figure>`;
 const checks=p.checks.map((text,i)=>`<label class="ct-test-item"><input type="checkbox" name="cataract-symptom" value="${i}"><span class="ct-test-box" aria-hidden="true">✓</span><span>${text}</span></label>`).join('');
 const checkTitle=key==='lens'||key.includes('exam')||key==='pediatric-dream'?'상담 전 확인해 보세요':'이런 증상이 있으신가요?';
 return `<article class="eye-detail unified-category" data-eye-page="${key}">${visual(key)}
 <section class="uc-about uc-section uc-wrap" id="explanation"><div class="uc-about-copy">${mark('About')}<h2>${p.title}</h2><p class="uc-highlight">${p.highlight}</p><div class="uc-description"><p>${p.about.join(' ')}</p></div></div><figure class="uc-about-photo"><img src="assets/${p.aboutImage}" alt="${p.title} 설명 이미지" loading="lazy"></figure></section>
 <section class="uc-compare uc-section uc-wrap" aria-label="${p.title} 시야 비교"><div class="ed-comparison uc-vision" data-effect="${p.effect}" data-mode="${key}" style="--ed-split:50%"><img src="assets/${p.scene}" alt="기준 시야를 위한 장면" draggable="false" loading="lazy"><div class="ed-comparison-haze" aria-hidden="true"><img src="assets/${p.scene}" alt="시야 변화를 연출한 장면" draggable="false" loading="lazy"><span class="uc-effect-overlay"></span></div><div class="ed-comparison-labels" aria-hidden="true"><span>기준 시야</span><span>시야 변화 예시</span></div><div class="ed-comparison-line" aria-hidden="true"><b>↔</b></div><input type="range" min="0" max="100" value="50" aria-label="${p.title} 시야 비교 경계 조절"></div><p class="uc-comparison-note">좌우로 움직여 비교해 보세요. 이해를 돕기 위한 연출 이미지입니다.</p></section>
 <section class="uc-issue uc-section" id="issue"><div class="uc-wrap"><div class="uc-section-heading">${mark('Issue')}<h2>${p.title}</h2></div><div class="uc-issue-text">${p.issue.map(line=>`<p>${line}</p>`).join('')}</div><div class="uc-graphics">${p.graphics.map(graphic).join('')}</div><p class="uc-issue-emphasis">${p.emphasis}</p><div class="uc-sources">자료: ${p.source.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name}</a>`).join(' · ')}</div></div></section>
 <section class="uc-causes uc-section" id="causes"><div class="uc-wrap uc-cause-layout"><div class="uc-cause-intro">${mark('Issue')}<h2>${p.title}</h2><h3>${key==='lens'||key.includes('exam')||key==='pediatric-dream'?'함께 살펴보는 기준':'원인과 위험요인'}</h3><p>${p.causes.map(([title])=>title).join(', ')} 등을 함께 살펴봅니다.</p><div class="uc-cause-controls"><button type="button" data-cause-direction="-1" aria-label="이전 원인 카드">←</button><button type="button" data-cause-direction="1" aria-label="다음 원인 카드">→</button></div></div><div class="uc-cause-track" tabindex="0" aria-label="${p.title} 원인과 관련 요인 카드">${p.causes.map(([title,description,image])=>`<article class="uc-cause-card"><div class="uc-cause-photo"><img src="assets/${image}" alt="${title} 관련 이미지" loading="lazy"></div><h3>${title}</h3><p>${description}</p></article>`).join('')}</div></div></section>
${p.urgent?`<aside class="uc-urgent uc-wrap" role="note">${p.urgent}</aside>`:''}
 ${reservation({title:checkTitle,checks,image:p.hero,alt:p.title+' 상담 안내 이미지',caption:'눈의 변화를 살피고,<br>필요한 진료를 안내합니다.'})}
 ${booking.dialog()}</article>`;
});
